(function () {
'use strict';
const html = document.documentElement;
const themeBtn = document.getElementById('themeBtn');
const themeIcon = document.getElementById('themeIcon');
const savedTheme = localStorage.getItem('pd-theme');
if (savedTheme) {
html.setAttribute('data-theme', savedTheme);
updateThemeIcon(savedTheme);
}
function toggleTheme() {
const current = html.getAttribute('data-theme');
const next = current === 'dark' ? 'light' : 'dark';
html.setAttribute('data-theme', next);
localStorage.setItem('pd-theme', next);
updateThemeIcon(next);
}
function updateThemeIcon(theme) {
if (!themeIcon) return;
if (theme === 'light') {
themeIcon.innerHTML =
'<circle cx="12" cy="12" r="5"/>' +
'<line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/>' +
'<line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/>' +
'<line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/>' +
'<line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/>';
} else {
themeIcon.innerHTML = '<path d="M21 12.79A9 9 0 1111.21 3 7 7 0 0021 12.79z"/>';
}
}
if (themeBtn) {
themeBtn.addEventListener('click', toggleTheme);
}
var heroVideo = document.querySelector('.hero-video');
if (heroVideo) {
document.addEventListener('visibilitychange', function () {
if (!document.hidden) {
heroVideo.currentTime = 0;
heroVideo.play();
}
});
var heroObserver = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (entry.isIntersecting) {
heroVideo.currentTime = 0;
heroVideo.play();
} else {
heroVideo.pause();
}
});
}, { threshold: 0.3 });
heroObserver.observe(document.getElementById('accueil'));
}
const nav = document.getElementById('navbar');
if (nav) {
window.addEventListener('scroll', function () {
nav.classList.toggle('scrolled', window.scrollY > 50);
}, { passive: true });
}
const hamburger = document.getElementById('hamburger');
const mobileMenu = document.getElementById('mobileMenu');
function openMenu() {
if (!hamburger || !mobileMenu) return;
hamburger.classList.add('open');
mobileMenu.classList.add('open');
document.body.style.overflow = 'hidden';
hamburger.setAttribute('aria-expanded', 'true');
}
function closeMenu() {
if (!hamburger || !mobileMenu) return;
hamburger.classList.remove('open');
mobileMenu.classList.remove('open');
document.body.style.overflow = '';
hamburger.setAttribute('aria-expanded', 'false');
}
function toggleMenu() {
if (mobileMenu && mobileMenu.classList.contains('open')) {
closeMenu();
} else {
openMenu();
}
}
if (hamburger) {
hamburger.addEventListener('click', toggleMenu);
}
if (mobileMenu) {
mobileMenu.querySelectorAll('a').forEach(function (a) {
a.addEventListener('click', closeMenu);
});
}
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape' && mobileMenu && mobileMenu.classList.contains('open')) {
closeMenu();
hamburger.focus();
}
});
var reveals = document.querySelectorAll('.reveal');
setTimeout(function () {
reveals.forEach(function (el) { el.classList.add('visible'); });
}, 800);
if ('IntersectionObserver' in window) {
reveals.forEach(function (el) { el.classList.remove('visible'); });
var io = new IntersectionObserver(function (entries) {
entries.forEach(function (e, i) {
if (e.isIntersecting) {
setTimeout(function () { e.target.classList.add('visible'); }, i * 80);
io.unobserve(e.target);
}
});
}, { threshold: 0.05, rootMargin: '0px 0px -40px 0px' });
reveals.forEach(function (el) { io.observe(el); });
}
document.querySelectorAll('a[href^="#"]').forEach(function (a) {
a.addEventListener('click', function (e) {
var hash = a.getAttribute('href');
if (hash === '#') return;
var target = document.querySelector(hash);
if (target) {
e.preventDefault();
target.scrollIntoView({ behavior: 'smooth' });
history.pushState(null, '', hash);
}
});
});
var bookingForm = document.getElementById('bookingForm');
var successBox = document.getElementById('successBox');
var errorBox = document.getElementById('errorBox');
if (bookingForm) {
bookingForm.addEventListener('submit', function (e) {
e.preventDefault();
if (successBox) successBox.style.display = 'none';
if (errorBox) errorBox.style.display = 'none';
var honeypot = bookingForm.querySelector('input[name="website"]');
if (honeypot && honeypot.value !== '') {
if (successBox) {
successBox.style.display = 'block';
successBox.textContent = '✦ Merci ! Votre demande a été envoyée. ✦';
}
return;
}
var name = bookingForm.querySelector('[name="name"]');
var phone = bookingForm.querySelector('[name="phone"]');
var email = bookingForm.querySelector('[name="email"]');
var service = bookingForm.querySelector('[name="service"]');
var datetime = bookingForm.querySelector('[name="datetime"]');
var pickup = bookingForm.querySelector('[name="pickup"]');
var destination = bookingForm.querySelector('[name="destination"]');
if (!name.value.trim() || !phone.value.trim() || !email.value.trim() || !service.value || !datetime.value || !pickup.value.trim()) {
showError('Veuillez remplir tous les champs obligatoires.');
return;
}
var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(email.value.trim())) {
showError('Veuillez saisir une adresse email valide.');
return;
}
var phoneClean = phone.value.replace(/[\s\-\.()]/g, '');
if (phoneClean.length < 10) {
showError('Veuillez saisir un numéro de téléphone valide.');
return;
}
var msg = '🚗 *NOUVELLE RÉSERVATION — Prestige Drive*\n\n';
msg += '👤 *Nom :* ' + bookingForm.querySelector('[name="name"]').value + '\n';
msg += '📞 *Téléphone :* ' + bookingForm.querySelector('[name="phone"]').value + '\n';
msg += '📧 *Email :* ' + bookingForm.querySelector('[name="email"]').value + '\n';
msg += '🚘 *Prestation :* ' + bookingForm.querySelector('[name="service"]').value + '\n';
msg += '📅 *Date/Heure :* ' + bookingForm.querySelector('[name="datetime"]').value + '\n';
msg += '📍 *Départ :* ' + bookingForm.querySelector('[name="pickup"]').value + '\n';
var dest = bookingForm.querySelector('[name="destination"]');
if (dest && dest.value.trim()) msg += '🏁 *Destination :* ' + dest.value + '\n';
var msgField = bookingForm.querySelector('[name="message"]');
if (msgField && msgField.value.trim()) msg += '💬 *Précisions :* ' + msgField.value + '\n';
if (successBox) {
successBox.style.display = 'block';
successBox.textContent = '✦ Merci ! Vous allez être redirigé vers WhatsApp pour confirmer votre réservation. ✦';
}
bookingForm.reset();
setTimeout(function () {
window.open('https://wa.me/33767500101?text=' + encodeURIComponent(msg), '_blank');
}, 600);
});
}
function showError(msg) {
if (errorBox) {
errorBox.style.display = 'block';
errorBox.textContent = msg;
}
}
var heroPhoto = document.querySelector('.hero-photo');
var heroSection = document.querySelector('.hero');
if (heroSection && heroPhoto) {
heroPhoto.addEventListener('animationend', function () {
heroPhoto.classList.add('parallax-ready');
});
heroSection.addEventListener('mousemove', function (e) {
if (!heroPhoto.classList.contains('parallax-ready')) return;
var rect = heroSection.getBoundingClientRect();
var x = (e.clientX - rect.left) / rect.width - 0.5;
var y = (e.clientY - rect.top) / rect.height - 0.5;
heroPhoto.style.transform = 'translate(' + (x * -30) + 'px, ' + (y * -24) + 'px) scale(1.06)';
});
heroSection.addEventListener('mouseleave', function () {
if (!heroPhoto.classList.contains('parallax-ready')) return;
heroPhoto.style.transform = 'translate(0, 0) scale(1)';
});
}
var tiltCards = document.querySelectorAll('.svc, .testi');
tiltCards.forEach(function (card) {
card.addEventListener('mousemove', function (e) {
var rect = card.getBoundingClientRect();
var x = (e.clientX - rect.left) / rect.width - 0.5;
var y = (e.clientY - rect.top) / rect.height - 0.5;
card.style.transform = 'perspective(800px) rotateY(' + (x * 10) + 'deg) rotateX(' + (-y * 8) + 'deg) scale(1.03)';
});
card.addEventListener('mouseleave', function () {
card.style.transform = 'perspective(800px) rotateY(0) rotateX(0) scale(1)';
});
});
var photoCard = document.getElementById('photoCard');
if (photoCard) {
var cardMedia = photoCard.querySelector('img') || photoCard.querySelector('video');
if (cardMedia) {
photoCard.addEventListener('mousemove', function (e) {
var rect = photoCard.getBoundingClientRect();
var x = (e.clientX - rect.left) / rect.width - 0.5;
var y = (e.clientY - rect.top) / rect.height - 0.5;
var moveX = x * 28;
var moveY = y * 28;
cardMedia.style.transform = 'translate(' + moveX + 'px, ' + moveY + 'px) scale(1.06)';
});
photoCard.addEventListener('mouseleave', function () {
cardMedia.style.transform = 'translate(0, 0) scale(1)';
});
}
}
var magneticBtns = document.querySelectorAll('.btn-gold, .btn-outline, .soc, .whatsapp-float, .nav-tel');
magneticBtns.forEach(function (btn) {
btn.addEventListener('mousemove', function (e) {
var rect = btn.getBoundingClientRect();
var x = e.clientX - rect.left - rect.width / 2;
var y = e.clientY - rect.top - rect.height / 2;
btn.style.transform = 'translate(' + (x * 0.2) + 'px, ' + (y * 0.2) + 'px)';
btn.style.transition = 'transform 0.15s ease';
});
btn.addEventListener('mouseleave', function () {
btn.style.transform = 'translate(0, 0)';
btn.style.transition = 'transform 0.4s ease';
});
});
var yearEl = document.getElementById('currentYear');
if (yearEl) {
yearEl.textContent = new Date().getFullYear();
}
var aboutVideo = document.querySelector('.about-video');
if (aboutVideo) {
var aboutObs = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (entry.isIntersecting) {
aboutVideo.play();
} else {
aboutVideo.pause();
}
});
}, { threshold: 0.3 });
aboutObs.observe(aboutVideo);
}
var statNums = document.querySelectorAll('.stat-num');
var countersStarted = false;
function animateCounters() {
if (countersStarted) return;
countersStarted = true;
statNums.forEach(function (el) {
var text = el.textContent.trim();
var match = text.match(/^([\d,\.]+)/);
if (!match) return;
var raw = match[1].replace(',', '.');
var target = parseFloat(raw);
var suffix = text.replace(match[1], '');
var isDecimal = raw.indexOf('.') !== -1;
var duration = 1600;
var start = performance.now();
function step(now) {
var elapsed = now - start;
var progress = Math.min(elapsed / duration, 1);
var ease = 1 - Math.pow(1 - progress, 3);
var current = target * ease;
if (isDecimal) {
el.textContent = current.toFixed(1).replace('.', ',') + suffix;
} else {
el.textContent = Math.floor(current) + suffix;
}
if (progress < 1) requestAnimationFrame(step);
}
el.textContent = isDecimal ? '0,0' + suffix : '0' + suffix;
requestAnimationFrame(step);
});
}
if (statNums.length && 'IntersectionObserver' in window) {
var statsSection = document.querySelector('.stats');
if (statsSection) {
var counterObs = new IntersectionObserver(function (entries) {
entries.forEach(function (e) {
if (e.isIntersecting) {
animateCounters();
counterObs.unobserve(e.target);
}
});
}, { threshold: 0.3 });
counterObs.observe(statsSection);
}
}
var progressBar = document.getElementById('formProgressBar');
if (bookingForm && progressBar) {
var requiredFields = bookingForm.querySelectorAll('[required]');
var totalFields = requiredFields.length;
function updateProgress() {
var filled = 0;
requiredFields.forEach(function (f) {
if (f.value && f.value.trim() !== '') filled++;
});
var pct = totalFields > 0 ? (filled / totalFields) * 100 : 0;
progressBar.style.width = pct + '%';
}
requiredFields.forEach(function (f) {
f.addEventListener('input', updateProgress);
f.addEventListener('change', updateProgress);
});
}
var originalFormSubmitHandler = null;
if (successBox) {
var origDisplay = successBox.style.display;
var mo = new MutationObserver(function () {
if (successBox.style.display === 'block') {
successBox.classList.add('show-confetti');
if (progressBar) progressBar.style.width = '100%';
setTimeout(function () {
successBox.classList.remove('show-confetti');
}, 2000);
}
});
mo.observe(successBox, { attributes: true, attributeFilter: ['style'] });
}
var backToTop = document.getElementById('backToTop');
if (backToTop) {
window.addEventListener('scroll', function () {
backToTop.classList.toggle('visible', window.scrollY > 600);
}, { passive: true });
backToTop.addEventListener('click', function () {
window.scrollTo({ top: 0, behavior: 'smooth' });
});
}
var canvas = document.getElementById('goldParticles');
if (canvas && window.innerWidth > 768) {
var ctx = canvas.getContext('2d');
var particles = [];
var particleCount = 30;
function resizeCanvas() {
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);
function Particle() {
this.reset();
}
Particle.prototype.reset = function () {
this.x = Math.random() * canvas.width;
this.y = Math.random() * canvas.height;
this.size = Math.random() * 2 + 0.5;
this.speedY = -(Math.random() * 0.3 + 0.1);
this.speedX = (Math.random() - 0.5) * 0.2;
this.opacity = Math.random() * 0.5 + 0.1;
this.fadeDir = Math.random() > 0.5 ? 0.003 : -0.003;
};
Particle.prototype.update = function () {
this.y += this.speedY;
this.x += this.speedX;
this.opacity += this.fadeDir;
if (this.opacity <= 0.05 || this.opacity >= 0.6) this.fadeDir *= -1;
if (this.y < -10) {
this.y = canvas.height + 10;
this.x = Math.random() * canvas.width;
}
};
Particle.prototype.draw = function () {
ctx.beginPath();
ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
ctx.fillStyle = 'rgba(201,168,76,' + this.opacity + ')';
ctx.fill();
};
for (var i = 0; i < particleCount; i++) {
particles.push(new Particle());
}
function animateParticles() {
ctx.clearRect(0, 0, canvas.width, canvas.height);
particles.forEach(function (p) {
p.update();
p.draw();
});
requestAnimationFrame(animateParticles);
}
animateParticles();
}
(function(){
var track = document.querySelector('.testi-track');
var cards = track ? Array.prototype.slice.call(track.children) : [];
var dotsWrap = document.querySelector('.testi-dots');
var prevBtn = document.querySelector('.testi-prev');
var nextBtn = document.querySelector('.testi-next');
if(!track || cards.length === 0) return;
var n = cards.length;
var current = 0;
function getVisible(){
if(window.innerWidth <= 768) return 1;
if(window.innerWidth <= 1024) return 2;
return 3;
}
function getGap(){
if(window.innerWidth <= 768) return 16;
return 20;
}
function getMaxPos(){ return Math.max(0, n - getVisible()); }
function sizeCards(){
var vis = getVisible();
var gap = getGap();
var vpW = track.parentElement.offsetWidth;
var cardW = (vpW - gap * (vis - 1)) / vis;
for(var i = 0; i < cards.length; i++){
cards[i].style.width = cardW + 'px';
}
return {cardW: cardW, gap: gap};
}
function slide(){
var dims = sizeCards();
var offset = current * (dims.cardW + dims.gap);
track.style.transform = 'translateX(-' + offset + 'px)';
updateDots();
}
function updateDots(){
var dots = dotsWrap.querySelectorAll('.testi-dot');
for(var j = 0; j < dots.length; j++){
dots[j].classList.toggle('active', j === current);
}
}
function buildDots(){
dotsWrap.innerHTML = '';
var max = getMaxPos();
for(var i = 0; i <= max; i++){
var dot = document.createElement('button');
dot.className = 'testi-dot' + (i === current ? ' active' : '');
dot.setAttribute('aria-label', 'Page ' + (i+1));
(function(idx){ dot.addEventListener('click', function(){ goTo(idx); }); })(i);
dotsWrap.appendChild(dot);
}
}
function goTo(idx){
var max = getMaxPos();
current = idx < 0 ? max : (idx > max ? 0 : idx);
slide();
}
prevBtn.addEventListener('click', function(){ goTo(current - 1); });
nextBtn.addEventListener('click', function(){ goTo(current + 1); });
var autoId = setInterval(function(){ goTo(current + 1); }, 4500);
var carousel = track.closest('.testi-carousel');
carousel.addEventListener('mouseenter', function(){ clearInterval(autoId); });
carousel.addEventListener('mouseleave', function(){
autoId = setInterval(function(){ goTo(current + 1); }, 4500);
});
window.addEventListener('resize', function(){
if(current > getMaxPos()) current = getMaxPos();
buildDots();
slide();
});
buildDots();
slide();
})();
if ('IntersectionObserver' in window) {
var lazySections = document.querySelectorAll('.section, .band, .trust-bar');
var lazyObs = new IntersectionObserver(function (entries) {
entries.forEach(function (e) {
if (e.isIntersecting) {
e.target.classList.add('loaded');
lazyObs.unobserve(e.target);
}
});
}, { threshold: 0.05 });
lazySections.forEach(function (s) {
s.classList.add('lazy-section');
lazyObs.observe(s);
});
}
})();